    #[arg(short = 'G', long)]
    glob: Option<String>,

    /// Do not modify files, print diff only
    #[arg(long)]
    dry_run: bool,

    /// Fail if working on files but none are found
    #[arg(long)]
    fail_no_files: bool,

    /// Process files in lexicographically sorted order
    #[arg(long)]
    sorted: bool,

    /// Do not ignore hidden files
    #[arg(short = 'H', long)]
    hidden: bool,

    /// Do not ignore .gitignored files
    #[arg(long)]
    gitignored: bool,

    /// Shell for completions
    #[arg(long)]
    completions: Option<String>,

    // Language scopes - Python
    #[arg(long)]
    python: Option<String>,

    // Language scopes - Rust
    #[arg(long)]
    rust: Option<String>,

