    #[arg(long)]
    go: Option<String>,

    // Language scopes - TypeScript
    #[arg(long)]
    typescript: Option<String>,

    // Language scopes - C#
    #[arg(long)]
    csharp: Option<String>,

    // Language scopes - C
    #[arg(long)]
    c: Option<String>,

    // Language scopes - HCL
    #[arg(long)]
    hcl: Option<String>,
}

fn main() {
    let cli = Cli::parse();

    // Handle completions
    if let Some(_shell) = cli.completions {
        // TODO: generate completions
        return;
    }

    // Read input
    let input = read_input();

    // Check for contradictory options
    if cli.delete && (cli.upper || cli.lower || cli.titlecase || cli.normalize || 
