            // Handle fail conditions
            if cli.fail_any && matched_count > 0 {
                eprintln!("Error: Error applying: Some input was in scope");
                process::exit(1);
            }
            if cli.fail_none && matched_count == 0 {
                eprintln!("Error: Error applying: No input was in scope");
                process::exit(1);
            }
        }
        Err(e) => {
            eprintln!("Error: {}", e);
            process::exit(1);
        }
    }
}

fn read_input() -> String {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).expect("Failed to read stdin");
