}

fn process_input(input: &str, cli: &Cli) -> Result<(String, usize), String> {
    let scope = cli.scope.as_ref().map(|s| s.as_str()).unwrap_or(".*");

    // Build regex pattern
    let pattern = if cli.literal_string {
