    let has_action = cli.upper || cli.lower || cli.titlecase || cli.normalize || 
                     cli.german || cli.symbols || cli.delete || cli.squeeze || 
                     cli.replacement.is_some();

    // Handle search mode (no actions, language scopes)
    if !has_action && (cli.python.is_some() || cli.rust.is_some() || cli.go.is_some() || 
                       cli.typescript.is_some() || cli.csharp.is_some() || cli.c.is_some() || 
                       cli.hcl.is_some()) {
        // Language scope search mode - not implemented yet
        return Err("Language scope search mode not yet implemented".to_string());
