        let count = re.find_iter(input).count();
        Ok((output, count))
    } else {
        // Apply transformations in order: replace, then upper/lower/etc
        let mut result = if let Some(replacement) = &cli.replacement {
            apply_replacement(input, &re, replacement)?
        } else {
            input.to_string()
        };

        // Count matches before applying other transformations
        let count = re.find_iter(input).count();

        // Apply other transformations
        if cli.upper || cli.lower || cli.titlecase || cli.normalize || cli.german || cli.symbols {
            result = apply_transformations(&result, &re, cli)?;
        }

        Ok((result, count))
    }
}

fn apply_replacement(input: &str, re: &Regex, replacement: &str) -> Result<String, String> {
    // Handle capture group substitution
    Ok(re.replace_all(input, replacement).to_string())
