        result = result.replacen(matched, &transformed, 1);
    }

    Ok(result)
}

fn transform_text(text: &str, cli: &Cli) -> Result<String, String> {
    let mut result = text.to_string();

    if cli.upper {
        result = result.to_uppercase();
    } else if cli.lower {
        result = result.to_lowercase();
    } else if cli.titlecase {
        result = to_titlecase(&result);
    }

    if cli.normalize {
        result = normalize_unicode(&result);
    }

    if cli.symbols {
        if cli.invert {
            result = invert_symbols(&result);
        } else {
            result = apply_symbols(&result);
        }
    }

    if cli.german {
        if cli.invert {
            result = invert_german(&result);
        } else {
            result = apply_german(&result);
        }
    }

    Ok(result)
}

fn to_titlecase(text: &str) -> String {
    let mut result = String::new();
    let mut capitalize_next = true;

    for ch in text.chars() {
        if ch.is_alphabetic() {
            if capitalize_next {
                result.push_str(&ch.to_uppercase().to_string());
                capitalize_next = false;
            } else {
                result.push_str(&ch.to_lowercase().to_string());
            }
        } else {
            result.push(ch);
            capitalize_next = true;
        }
    }

    result
}

