        .filter(|c| !unicode_normalization::is_combining_mark(*c))
        .collect()
}

fn apply_symbols(text: &str) -> String {
    let replacements = [
        ("!=", "≠"),
        ("->", "→"),
        ("<-", "←"),
        ("=>", "⇒"),
        ("<=", "≤"),
        (">=", "≥"),
        ("<<", "«"),
        (">>", "»"),
        ("...", "…"),
    ];

    let mut result = text.to_string();
    for (ascii, unicode) in &replacements {
        result = result.replace(ascii, unicode);
    }
    result
}

fn invert_symbols(text: &str) -> String {
    let replacements = [
        ("≠", "!="),
        ("→", "->"),
        ("←", "<-"),
        ("⇒", "=>"),
        ("≤", "<="),
        ("≥", ">="),
        ("«", "<<"),
        ("»", ">>"),
        ("…", "..."),
    ];

    let mut result = text.to_string();
    for (unicode, ascii) in &replacements {
        result = result.replace(unicode, ascii);
    }
    result
}

