    for (unicode, ascii) in &replacements {
        result = result.replace(unicode, ascii);
    }
    result
}

fn squeeze_matches(input: &str, re: &Regex) -> String {
    let mut result = String::new();
    let mut last_end = 0;
    let mut last_match: Option<String> = None;

    for cap in re.find_iter(input) {
        let matched = input[cap.start()..cap.end()].to_string();

        // Add text between last match and current match
        if cap.start() > last_end {
            result.push_str(&input[last_end..cap.start()]);
            last_match = None;
        }

        // Only add if different from last match or is first match after non-match
        if last_match.as_ref() != Some(&matched) {
            result.push_str(&matched);
            last_match = Some(matched);
        }

        last_end = cap.end();
    }

    // Add remaining text
    if last_end < input.len() {
        result.push_str(&input[last_end..]);
    }

    result
}
