    let mut scope_set = false;
    let mut after_double_dash = false;

    while i < args.len() {
        let arg = &args[i];

        if arg == "--" {
            after_double_dash = true;
            i += 1;
            // Next argument is replacement
            if i < args.len() {
                replacement = Some(args[i].clone());
                i += 1;
            }
            continue;
