    }

    // Simple string matching (not regex for now)
    let pattern = scope;

    if delete {
        let output = input.replace(pattern, "");
        let match_count = count_matches(input, pattern);
        Ok((output, match_count))
    } else if squeeze {
        let output = squeeze_matches(input, pattern);
        let match_count = count_matches(input, pattern);
        Ok((output, match_count))
    } else {
        let mut result = if let Some(repl) = replacement {
            apply_replacement(input, pattern, repl)?
        } else {
            input.to_string()
        };

        let match_count = count_matches(input, pattern);

        if upper || lower || titlecase || normalize || german || symbols {
            result = apply_transformations(&result, pattern, upper, lower, titlecase, 
                                          normalize, german, symbols, invert)?;
        }

        Ok((result, match_count))
