}

fn apply_replacement(input: &str, pattern: &str, replacement: &str) -> Result<String, String> {
    Ok(input.replace(pattern, replacement))
}

fn apply_transformations(input: &str, pattern: &str, upper: bool, lower: bool, titlecase: bool,
                        normalize: bool, german: bool, symbols: bool, invert: bool) -> Result<String, String> {
    let mut result = String::new();
    let mut last_pos = 0;

    for (start, end) in find_all_match_ranges(input, pattern) {
        result.push_str(&input[last_pos..start]);
        let matched = &input[start..end];
        let transformed = transform_text(matched, upper, lower, titlecase, normalize, german, symbols, invert)?;
        result.push_str(&transformed);
        last_pos = end;
    }
    result.push_str(&input[last_pos..]);

    Ok(result)
}

fn find_all_match_ranges(input: &str, pattern: &str) -> Vec<(usize, usize)> {
    let mut ranges = Vec::new();
    let mut start = 0;

    while let Some(pos) = input[start..].find(pattern) {
        let absolute_start = start + pos;
        let absolute_end = absolute_start + pattern.len();
        ranges.push((absolute_start, absolute_end));
        start = absolute_end;
    }

    ranges
}

fn transform_text(text: &str, upper: bool, lower: bool, titlecase: bool, normalize: bool,
                 german: bool, symbols: bool, invert: bool) -> Result<String, String> {
    let mut result = text.to_string();

    if upper {
        result = result.to_uppercase();
    } else if lower {
        result = result.to_lowercase();
    } else if titlecase {
        result = to_titlecase(&result);
    }

    if normalize {
        result = normalize_unicode(&result);
    }

    if symbols {
        if invert {
            result = invert_symbols(&result);
        } else {
            result = apply_symbols(&result);
        }
    }

    if german {
        if invert {
            result = invert_german(&result);
        } else {
            result = apply_german(&result);
        }
    }

    Ok(result)
}

fn to_titlecase(text: &str) -> String {
    let mut result = String::new();
    let mut capitalize_next = true;

    for ch in text.chars() {
        if ch.is_alphabetic() {
            if capitalize_next {
                for uc in ch.to_uppercase() {
                    result.push(uc);
                }
                capitalize_next = false;
            } else {
                for lc in ch.to_lowercase() {
                    result.push(lc);
                }
            }
        } else {
            result.push(ch);
            capitalize_next = true;
        }
    }

    result
}

fn normalize_unicode(text: &str) -> String {
    // Remove diacritics by decomposing and filtering
    let mut result = String::new();
    for ch in text.chars() {
        match ch {
            'à' | 'á' | 'â' | 'ã' | 'ä' | 'å' => result.push('a'),
            'è' | 'é' | 'ê' | 'ë' => result.push('e'),
            'ì' | 'í' | 'î' | 'ï' => result.push('i'),
            'ò' | 'ó' | 'ô' | 'õ' | 'ö' | 'ø' => result.push('o'),
            'ù' | 'ú' | 'û' | 'ü' => result.push('u'),
            'ý' | 'ÿ' => result.push('y'),
            'ñ' => result.push('n'),
            'ç' => result.push('c'),
            'À' | 'Á' | 'Â' | 'Ã' | 'Ä' | 'Å' => result.push('A'),
            'È' | 'É' | 'Ê' | 'Ë' => result.push('E'),
            'Ì' | 'Í' | 'Î' | 'Ï' => result.push('I'),
            'Ò' | 'Ó' | 'Ô' | 'Õ' | 'Ö' | 'Ø' => result.push('O'),
            'Ù' | 'Ú' | 'Û' | 'Ü' => result.push('U'),
            'Ý' => result.push('Y'),
            'Ñ' => result.push('N'),
            'Ç' => result.push('C'),
            _ => result.push(ch),
        }
    }
    result
}

fn apply_symbols(text: &str) -> String {
    text.replace("!=", "≠")
        .replace("->", "→")
        .replace("<-", "←")
        .replace("=>", "⇒")
        .replace("<=", "≤")
        .replace(">=", "≥")
        .replace("<<", "«")
        .replace(">>", "»")
        .replace("...", "…")
