fn invert_symbols(text: &str) -> String {
    text.replace("≠", "!=")
        .replace("→", "->")
        .replace("←", "<-")
        .replace("⇒", "=>")
        .replace("≤", "<=")
        .replace("≥", ">=")
        .replace("«", "<<")
        .replace("»", ">>")
        .replace("…", "...")
}

fn apply_german(text: &str) -> String {
    text.replace("ae", "ä")
        .replace("oe", "ö")
        .replace("ue", "ü")
        .replace("Ae", "Ä")
        .replace("Oe", "Ö")
        .replace("Ue", "Ü")
        .replace("ss", "ß")
}

fn invert_german(text: &str) -> String {
    text.replace("ä", "ae")
        .replace("ö", "oe")
        .replace("ü", "ue")
        .replace("Ä", "Ae")
        .replace("Ö", "Oe")
        .replace("Ü", "Ue")
        .replace("ß", "ss")
