fn squeeze_matches(input: &str, pattern: &str) -> String {
    let mut result = String::new();
    let mut last_was_match = false;
    let mut i = 0;

    while i < input.len() {
        if input[i..].starts_with(pattern) {
            if !last_was_match {
                result.push_str(pattern);
                last_was_match = true;
            }
            i += pattern.len();
        } else {
            let ch = input.chars().nth(i).unwrap_or('\0');
            result.push(ch);
            last_was_match = false;
            i += ch.len_utf8();
        }
    }

    result
