        find_pattern_matches(text, &self.pattern)
    }

    pub fn replace_all(&self, text: &str, replacement: &str) -> String {
        if self.pattern.is_empty() {
            return text.to_string();
        }

        // Handle basic regex patterns and replacements
        let mut result = String::new();
        let mut last_end = 0;

        for (start, end) in self.find_iter(text) {
            result.push_str(&text[last_end..start]);

            // Handle capture group replacements
            let matched = &text[start..end];
            let replaced = expand_replacement(&matched, replacement, text, start, end, &self.pattern);
            result.push_str(&replaced);

            last_end = end;
        }
        result.push_str(&text[last_end..]);
        result
    }
}

fn expand_replacement(matched: &str, replacement: &str, text: &str, start: usize, end: usize, pattern: &str) -> String {
    let mut result = replacement.to_string();

    // Handle $0 (full match)
    result = result.replace("$0", matched);

    // Handle $1, $2, etc. (capture groups)
    // For now, do simple handling
    if let Ok(regex) = SimpleRegex::new(pattern) {
        let captures = extract_captures(pattern, matched);
        for (i, cap) in captures.iter().enumerate() {
            result = result.replace(&format!("${}", i + 1), cap);
        }

        // Handle named captures like $NAME
        let named_caps = extract_named_captures(pattern, matched);
        for (name, value) in named_caps {
            result = result.replace(&format!("${}", name), &value);
        }
    }

    result
}

fn find_pattern_matches(text: &str, pattern: &str) -> Vec<(usize, usize)> {
    let mut matches = Vec::new();

    if pattern.is_empty() {
        return matches;
    }

    // Handle literal matches and simple regex patterns
    if is_simple_pattern(pattern) {
        let mut start = 0;
        while let Some(pos) = text[start..].find(&extract_literal(pattern)) {
            let absolute_start = start + pos;
            let absolute_end = absolute_start + extract_literal(pattern).len();
            matches.push((absolute_start, absolute_end));
            start = absolute_end;
        }
    } else {
        // Try to match as regex
        match_regex(text, pattern, &mut matches);
    }

    matches
}

fn is_simple_pattern(pattern: &str) -> bool {
    // Check if pattern contains regex special characters
    !pattern.contains('[') && !pattern.contains('(') && !pattern.contains('.') && 
    !pattern.contains('*') && !pattern.contains('+') && !pattern.contains('?') &&
    !pattern.contains('^') && !pattern.contains('$') && !pattern.contains('|') &&
    !pattern.contains('\\')
}

