fn process_input(input: &str, scope: &str, replacement: Option<&str>, upper: bool, lower: bool,
                titlecase: bool, normalize: bool, german: bool, symbols: bool, delete: bool,
                squeeze: bool, literal_string: bool, invert: bool, _fail_any: bool, _fail_none: bool,
                _only_matching: bool, _count: bool) -> Result<(String, usize), String> {

    let has_action = upper || lower || titlecase || normalize || german || symbols || 
                     delete || squeeze || replacement.is_some();

    if !has_action {
        eprintln!("[2026-04-28T23:47:28.496041Z ERROR srgn] No actions specified, and not in search mode. Will return input unchanged, if any.");
        return Ok((input.to_string(), 0));
    }

    // Build regex pattern
    let pattern_str = if literal_string {
        format!("(?-u)(?:{})(?u)", regex_escape(scope))
    } else {
        scope.to_string()
    };

    let re = SimpleRegex::new(&pattern_str)
        .map_err(|e| format!("Invalid pattern: {}", e))?;

    if delete {
        let output = re.replace_all(input, "");
        let match_count = count_matches(input, &re);
        Ok((output, match_count))
    } else if squeeze {
        let output = squeeze_matches(input, &re);
        let match_count = count_matches(input, &re);
        Ok((output, match_count))
    } else {
        let mut result = if let Some(repl) = replacement {
            re.replace_all(input, repl)
        } else {
            input.to_string()
        };

        let match_count = count_matches(input, &re);

        if upper || lower || titlecase || normalize || german || symbols {
            result = apply_transformations(&result, &re, upper, lower, titlecase, 
                                          normalize, german, symbols, invert)?;
        }

        Ok((result, match_count))
    }
