        .map_err(|e| format!("Invalid pattern: {}", e))?;

    let match_count = count_matches(input, &re);

    if !has_action {
        eprintln!("[2026-04-28T23:47:28.496041Z ERROR srgn] No actions specified, and not in search mode. Will return input unchanged, if any.");

