fn to_titlecase(text: &str) -> String {
    let mut result = String::new();
    let mut capitalize_next = true;

    for ch in text.chars() {
        if ch.is_alphabetic() {
            if capitalize_next {
                for uc in ch.to_uppercase() {
                    result.push(uc);
                }
                capitalize_next = false;
            } else {
                for lc in ch.to_lowercase() {
                    result.push(lc);
                }
            }
        } else {
            result.push(ch);
            capitalize_next = true;
        }
    }

    result
}

fn normalize_unicode(text: &str) -> String {
    let mut result = String::new();
    for ch in text.chars() {
        match ch {
            'à' | 'á' | 'â' | 'ã' | 'ä' | 'å' => result.push('a'),
            'è' | 'é' | 'ê' | 'ë' => result.push('e'),
            'ì' | 'í' | 'î' | 'ï' => result.push('i'),
            'ò' | 'ó' | 'ô' | 'õ' | 'ö' | 'ø' => result.push('o'),
            'ù' | 'ú' | 'û' | 'ü' => result.push('u'),
            'ý' | 'ÿ' => result.push('y'),
            'ñ' => result.push('n'),
            'ç' => result.push('c'),
            'À' | 'Á' | 'Â' | 'Ã' | 'Ä' | 'Å' => result.push('A'),
            'È' | 'É' | 'Ê' | 'Ë' => result.push('E'),
            'Ì' | 'Í' | 'Î' | 'Ï' => result.push('I'),
            'Ò' | 'Ó' | 'Ô' | 'Õ' | 'Ö' | 'Ø' => result.push('O'),
            'Ù' | 'Ú' | 'Û' | 'Ü' => result.push('U'),
            'Ý' => result.push('Y'),
            'Ñ' => result.push('N'),
            'Ç' => result.push('C'),
            _ => result.push(ch),
        }
    }
    result
}

fn apply_symbols(text: &str) -> String {
    text.replace("!=", "≠")
        .replace("->", "→")
        .replace("<-", "←")
        .replace("=>", "⇒")
        .replace("<=", "≤")
        .replace(">=", "≥")
        .replace("<<", "«")
        .replace(">>", "»")
        .replace("...", "…")
}

fn invert_symbols(text: &str) -> String {
    text.replace("≠", "!=")
        .replace("→", "->")
        .replace("←", "<-")
        .replace("⇒", "=>")
        .replace("≤", "<=")
        .replace("≥", ">=")
        .replace("«", "<<")
        .replace("»", ">>")
        .replace("…", "...")
}

fn apply_german(text: &str) -> String {
    text.replace("ae", "ä")
        .replace("oe", "ö")
        .replace("ue", "ü")
        .replace("Ae", "Ä")
        .replace("Oe", "Ö")
        .replace("Ue", "Ü")
        .replace("ss", "ß")
}

fn invert_german(text: &str) -> String {
    text.replace("ä", "ae")
        .replace("ö", "oe")
        .replace("ü", "ue")
        .replace("Ä", "Ae")
        .replace("Ö", "Oe")
        .replace("Ü", "Ue")
        .replace("ß", "ss")
}

fn squeeze_matches(input: &str, re: &SimpleRegex) -> String {
    let mut result = String::new();
    let mut last_was_match = false;
    let mut last_end = 0;

    for (start, end) in re.find_iter(input) {
        if start > last_end {
            result.push_str(&input[last_end..start]);
            last_was_match = false;
        }

        if !last_was_match {
            result.push_str(&input[start..end]);
            last_was_match = true;
        }

        last_end = end;
    }
    result.push_str(&input[last_end..]);
    result
}

fn print_help() {
    println!("A grep-like tool which understands source code syntax and allows for manipulation in");
    println!("addition to search");
    println!();
    println!("Usage: executable [OPTIONS] [SCOPE] [-- <REPLACEMENT>]");
    println!();
    println!("Arguments:");
    println!("  [SCOPE]  Scope to apply to, as a regular expression pattern");
    println!();
    println!("Options:");
    println!("  -u, --upper              Uppercase anything in scope");
    println!("  -l, --lower              Lowercase anything in scope");
    println!("  -t, --titlecase          Titlecase anything in scope");
    println!("  -n, --normalize          Normalize anything in scope");
    println!("  -g, --german             Perform German substitutions");
    println!("  -S, --symbols            Perform symbol substitutions");
    println!("  -d, --delete             Delete anything in scope");
    println!("  -s, --squeeze            Squeeze consecutive occurrences");
    println!("  -L, --literal-string     Use literal string instead of regex");
    println!("  -i, --invert             Invert actions where applicable");
    println!("  --fail-any               Fail if any match is found");
    println!("  --fail-none              Fail if no match is found");
    println!("  --only-matching          Print only matched portions");
    println!("  --line-numbers           Include line numbers");
    println!("  --count                  Print only the count");
    println!("  -V, --version            Print version");
    println!("  -h, --help               Print help");
}
