        return;
    }

    // Read input
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).expect("Failed to read stdin");

    // Check for contradictory options
    if delete && (upper || lower || titlecase || normalize || german || symbols || replacement.is_some()) {
        eprintln!("error: --delete cannot be combined with other actions");
        process::exit(2);
    }

    // Process input
    match process_input(&input, &scope, replacement.as_deref(), upper, lower, titlecase, 
                       normalize, german, symbols, delete, squeeze, literal_string, invert,
                       fail_any, fail_none, _only_matching, _count) {
        Ok((output, matched_count)) => {
