fn process_input(input: &str, scope: &str, replacement: Option<&str>, upper: bool, lower: bool,
                titlecase: bool, normalize: bool, german: bool, symbols: bool, delete: bool,
                squeeze: bool, literal_string: bool, invert: bool, fail_any: bool, fail_none: bool,
                _only_matching: bool, _count: bool) -> Result<(String, usize), String> {

    let has_action = upper || lower || titlecase || normalize || german || symbols || 
                     delete || squeeze || replacement.is_some();

    // First, count the matches for fail conditions
    let pattern_str = if literal_string {
        scope.to_string()
    } else {
        scope.to_string()
    };

    let re = SimpleRegex::new_with_literal_flag(&pattern_str, literal_string)
        .map_err(|e| format!("Invalid pattern: {}", e))?;

    let match_count = count_matches(input, &re);

    if !has_action {
        eprintln!("[2026-04-28T23:47:28.496041Z ERROR srgn] No actions specified, and not in search mode. Will return input unchanged, if any.");

        // Still check fail conditions
        if fail_any && match_count > 0 {
            return Err("Error applying: Some input was in scope".to_string());
        }
        if fail_none && match_count == 0 {
            return Err("Error applying: No input was in scope".to_string());
        }

        return Ok((input.to_string(), match_count));
    }

    if delete {
        let output = re.replace_all(input, "");
        Ok((output, match_count))
    } else if squeeze {
        let output = squeeze_matches(input, &re);
        Ok((output, match_count))
    } else {
        let mut result = if let Some(repl) = replacement {
            re.replace_all(input, repl)
        } else {
            input.to_string()
        };

        if upper || lower || titlecase || normalize || german || symbols {
            result = apply_transformations(&result, &re, upper, lower, titlecase, 
                                          normalize, german, symbols, invert)?;
        }

        Ok((result, match_count))
    }
}

fn count_matches(input: &str, re: &SimpleRegex) -> usize {
    re.find_iter(input).len()
}

fn apply_transformations(input: &str, re: &SimpleRegex, upper: bool, lower: bool, titlecase: bool,
                        normalize: bool, german: bool, symbols: bool, invert: bool) -> Result<String, String> {
    let mut result = String::new();
    let mut last_end = 0;

    for (start, end) in re.find_iter(input) {
        result.push_str(&input[last_end..start]);
        let matched = &input[start..end];
        let transformed = transform_text(matched, upper, lower, titlecase, normalize, german, symbols, invert)?;
        result.push_str(&transformed);
        last_end = end;
    }
    result.push_str(&input[last_end..]);

    Ok(result)
}

fn transform_text(text: &str, upper: bool, lower: bool, titlecase: bool, normalize: bool,
                 german: bool, symbols: bool, invert: bool) -> Result<String, String> {
    let mut result = text.to_string();

    // Apply actions in order
    if german {
        if invert {
            result = invert_german(&result);
        } else {
            result = apply_german(&result);
        }
    }

    if symbols {
        if invert {
            result = invert_symbols(&result);
        } else {
            result = apply_symbols(&result);
        }
    }

    if normalize {
        result = normalize_unicode(&result);
    }

    if upper {
        result = result.to_uppercase();
    } else if lower {
        result = result.to_lowercase();
    } else if titlecase {
        result = to_titlecase(&result);
    }

    Ok(result)
}

fn to_titlecase(text: &str) -> String {
    let mut result = String::new();
    let mut capitalize_next = true;

    for ch in text.chars() {
        if ch.is_alphabetic() {
            if capitalize_next {
                for uc in ch.to_uppercase() {
                    result.push(uc);
                }
                capitalize_next = false;
            } else {
                for lc in ch.to_lowercase() {
                    result.push(lc);
                }
            }
        } else {
            result.push(ch);
            capitalize_next = true;
        }
    }

    result
}

fn normalize_unicode(text: &str) -> String {
    let mut result = String::new();
    for ch in text.chars() {
        match ch {
            'à' | 'á' | 'â' | 'ã' | 'ä' | 'å' => result.push('a'),
            'è' | 'é' | 'ê' | 'ë' => result.push('e'),
            'ì' | 'í' | 'î' | 'ï' => result.push('i'),
            'ò' | 'ó' | 'ô' | 'õ' | 'ö' | 'ø' => result.push('o'),
            'ù' | 'ú' | 'û' | 'ü' => result.push('u'),
            'ý' | 'ÿ' => result.push('y'),
            'ñ' => result.push('n'),
            'ç' => result.push('c'),
            'À' | 'Á' | 'Â' | 'Ã' | 'Ä' | 'Å' => result.push('A'),
            'È' | 'É' | 'Ê' | 'Ë' => result.push('E'),
            'Ì' | 'Í' | 'Î' | 'Ï' => result.push('I'),
            'Ò' | 'Ó' | 'Ô' | 'Õ' | 'Ö' | 'Ø' => result.push('O'),
            'Ù' | 'Ú' | 'Û' | 'Ü' => result.push('U'),
            'Ý' => result.push('Y'),
            'Ñ' => result.push('N'),
            'Ç' => result.push('C'),
            _ => result.push(ch),
        }
    }
    result
}

fn apply_symbols(text: &str) -> String {
    text.replace("!=", "≠")
        .replace("->", "→")
        .replace("<-", "←")
        .replace("=>", "⇒")
        .replace("<=", "≤")
        .replace(">=", "≥")
        .replace("<<", "«")
        .replace(">>", "»")
        .replace("...", "…")
}

fn invert_symbols(text: &str) -> String {
    text.replace("≠", "!=")
        .replace("→", "->")
        .replace("←", "<-")
        .replace("⇒", "=>")
        .replace("≤", "<=")
        .replace("≥", ">=")
        .replace("«", "<<")
        .replace("»", ">>")
        .replace("…", "...")
}

fn apply_german(text: &str) -> String {
    text.replace("ae", "ä")
        .replace("oe", "ö")
        .replace("ue", "ü")
        .replace("Ae", "Ä")
        .replace("Oe", "Ö")
        .replace("Ue", "Ü")
        .replace("ss", "ß")
}

fn invert_german(text: &str) -> String {
    text.replace("ä", "ae")
        .replace("ö", "oe")
        .replace("ü", "ue")
        .replace("Ä", "Ae")
        .replace("Ö", "Oe")
        .replace("Ü", "Ue")
        .replace("ß", "ss")
}

fn squeeze_matches(input: &str, re: &SimpleRegex) -> String {
    let mut result = String::new();
    let mut last_was_match = false;
    let mut last_end = 0;

    for (start, end) in re.find_iter(input) {
        if start > last_end {
            result.push_str(&input[last_end..start]);
            last_was_match = false;
        }

        if !last_was_match {
            result.push_str(&input[start..end]);
            last_was_match = true;
        }

        last_end = end;
    }
    result.push_str(&input[last_end..]);
    result
}

