pub struct SimpleRegex {
    pattern: String,
    is_literal: bool,
}

impl SimpleRegex {
    pub fn new_with_literal_flag(pattern: &str, is_literal: bool) -> Result<Self, String> {
        Ok(SimpleRegex {
            pattern: pattern.to_string(),
            is_literal,
        })
    }

    pub fn find_iter(&self, text: &str) -> Vec<(usize, usize)> {
        if self.is_literal {
            find_literal_matches(text, &self.pattern)
        } else {
            find_matches(text, &self.pattern)
        }
    }

    pub fn replace_all(&self, text: &str, replacement: &str) -> String {
        let mut result = String::new();
        let mut last_end = 0;

        for (start, end) in self.find_iter(text) {
            result.push_str(&text[last_end..start]);

            let matched = &text[start..end];
            let replaced = expand_replacement(matched, replacement, &self.pattern);
            result.push_str(&replaced);

            last_end = end;
        }
        result.push_str(&text[last_end..]);
        result
    }
}

fn find_literal_matches(text: &str, pattern: &str) -> Vec<(usize, usize)> {
    let mut matches = Vec::new();
    let mut start = 0;

    while let Some(pos) = text[start..].find(pattern) {
        let absolute_start = start + pos;
        let absolute_end = absolute_start + pattern.len();
        matches.push((absolute_start, absolute_end));
        start = absolute_end;
    }

    matches
}

fn find_matches(text: &str, pattern: &str) -> Vec<(usize, usize)> {
    let mut matches = Vec::new();

    if pattern.is_empty() {
        return matches;
    }

    // Handle specific patterns
    if pattern == ".*" {
        if !text.is_empty() {
            matches.push((0, text.len()));
        }
        return matches;
    }

    // Handle character class patterns with repetition like [0-9]+
    if pattern.starts_with('[') && pattern.len() > 2 {
        if let Some(close_bracket) = pattern.find(']') {
            let rest = &pattern[close_bracket + 1..];
            let char_class = &pattern[1..close_bracket];

            if rest == "+" {
                return find_char_class_repetition(text, char_class, 1, usize::MAX);
            } else if rest == "*" {
                return find_char_class_repetition(text, char_class, 0, usize::MAX);
            } else if rest == "?" {
                return find_char_class_repetition(text, char_class, 0, 1);
            } else if rest.is_empty() {
                return find_char_class_matches(text, char_class);
            }
        }
    }

    // Handle character class patterns like [abc], [a-z], [wW]
    if pattern.starts_with('[') {
        return find_char_class_matches(text, pattern);
    }

    // Handle alternation patterns like a|b
    if pattern.contains('|') && !pattern.contains("(?") {
        return find_alternation_matches(text, pattern);
    }

    // Handle repetition patterns like a+, a*, a?
    if pattern.ends_with('+') {
        let base = &pattern[..pattern.len() - 1];
        return find_repetition_matches(text, base, 1, usize::MAX);
    }

    if pattern.ends_with('*') {
        let base = &pattern[..pattern.len() - 1];
        return find_repetition_matches(text, base, 0, usize::MAX);
    }

    if pattern.ends_with('?') {
        let base = &pattern[..pattern.len() - 1];
        return find_repetition_matches(text, base, 0, 1);
    }

    // Handle dot patterns like h(.*)o
    if pattern.contains('.') {
        return find_dot_matches(text, pattern);
    }

    // Default: find literal matches
    find_literal_matches(text, pattern)
}

fn find_char_class_matches(text: &str, char_class: &str) -> Vec<(usize, usize)> {
    let mut matches = Vec::new();

    let class_str = if char_class.starts_with('[') && char_class.ends_with(']') {
        &char_class[1..char_class.len()-1]
    } else {
        char_class
    };

    for (i, ch) in text.char_indices() {
        if char_matches(ch, class_str) {
            matches.push((i, i + ch.len_utf8()));
        }
    }

    matches
}

fn find_char_class_repetition(text: &str, char_class: &str, min: usize, max: usize) -> Vec<(usize, usize)> {
    let mut matches = Vec::new();
    let mut i = 0;
    let text_chars: Vec<char> = text.chars().collect();

    while i < text_chars.len() {
        let start = i;
        let mut count = 0;

        while i < text_chars.len() && count < max && char_matches(text_chars[i], char_class) {
            count += 1;
            i += 1;
        }

        if count >= min {
            // Calculate byte positions
            let byte_start = text.char_indices().nth(start).map(|(pos, _)| pos).unwrap_or(0);
            let byte_end = if i < text_chars.len() {
                text.char_indices().nth(i).map(|(pos, _)| pos).unwrap_or(text.len())
            } else {
                text.len()
            };

            matches.push((byte_start, byte_end));
        }

        if count == 0 {
            i += 1;
        }
    }

    matches
}

fn char_matches(ch: char, char_class: &str) -> bool {
    let chars: Vec<char> = char_class.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        if i + 2 < chars.len() && chars[i + 1] == '-' {
            // Range
            let start = chars[i];
            let end = chars[i + 2];
            if ch >= start && ch <= end {
                return true;
            }
            i += 3;
        } else {
            if ch == chars[i] {
                return true;
            }
            i += 1;
        }
    }

    false
}

fn find_alternation_matches(text: &str, pattern: &str) -> Vec<(usize, usize)> {
    let mut matches = Vec::new();
    let alternatives: Vec<&str> = pattern.split('|').collect();

    for alt in alternatives {
        let alt_matches = find_matches(text, alt);
        matches.extend(alt_matches);
    }

    // Sort and deduplicate
    matches.sort_by_key(|m| m.0);
    matches.dedup_by_key(|m| m.0);

    matches
}

fn find_repetition_matches(text: &str, base: &str, min: usize, max: usize) -> Vec<(usize, usize)> {
    let mut matches = Vec::new();

    if base.is_empty() {
        return matches;
    }

    let mut start = 0;
    while let Some(pos) = text[start..].find(base) {
        let absolute_start = start + pos;
        let mut end = absolute_start + base.len();
        let mut count = 1;

        while count < max && text[end..].starts_with(base) {
            end += base.len();
            count += 1;
        }

        if count >= min {
            matches.push((absolute_start, end));
        }

        start = absolute_start + 1;
    }

    matches
}

fn find_dot_matches(text: &str, pattern: &str) -> Vec<(usize, usize)> {
    // Handle patterns like h(.*)o
    let parts: Vec<&str> = pattern.split('.').collect();

    if parts.len() < 2 {
        return find_literal_matches(text, pattern);
    }

    let mut matches = Vec::new();
    let prefix = parts[0];
    let suffix = parts.get(1).map(|s| s.trim_start_matches('*')).unwrap_or("");

    let mut start = 0;
    while let Some(prefix_pos) = text[start..].find(prefix) {
        let prefix_absolute = start + prefix_pos;
        let after_prefix = prefix_absolute + prefix.len();

        if let Some(suffix_pos) = text[after_prefix..].find(suffix) {
            let suffix_absolute = after_prefix + suffix_pos;
            let match_end = suffix_absolute + suffix.len();
            matches.push((prefix_absolute, match_end));
            start = prefix_absolute + 1;
        } else {
            break;
        }
    }

    matches
}

fn expand_replacement(matched: &str, replacement: &str, pattern: &str) -> String {
    let mut result = replacement.to_string();

    // Handle $0 (full match)
    result = result.replace("$0", matched);

    // Handle $1, $2, etc. (capture groups) - for now, just support full match
    result = result.replace("$1", matched);

    // Handle named captures if pattern contains them
    if pattern.contains("(?P<") {
        // Parse named groups from pattern
        let name_captures = extract_named_groups(pattern, matched);
        for (name, value) in name_captures {
            result = result.replace(&format!("${}", name), &value);
        }
    }

    result
}

fn extract_named_groups(pattern: &str, _matched: &str) -> Vec<(String, String)> {
    let mut groups = Vec::new();
    let mut i = 0;
    let chars: Vec<char> = pattern.chars().collect();

    while i < chars.len() {
        if i + 3 < chars.len() && chars[i] == '(' && chars[i + 1] == '?' && 
           chars[i + 2] == 'P' && chars[i + 3] == '<' {
            i += 4;
            let mut name = String::new();
            while i < chars.len() && chars[i] != '>' {
                name.push(chars[i]);
                i += 1;
            }

            if i < chars.len() && chars[i] == '>' {
                // For now, use the matched text as the group value
                groups.push((name, _matched.to_string()));
                i += 1;
            }
        } else {
            i += 1;
        }
    }

    groups
}
